import{obtenerElemento,asignarTexto,asignarHtml,formatearNumero,limitar,clasificarUv}from"./utils.js";import{inicializarReloj,inicializarNavegacion}from"./ui.js";import{nivelLluviaDesdeTasa,obtenerIconoLluvia}from"./lluvia.js";import{validarCondiciones,esEstacionValida}from"./validation.js";import{inicializarPerformance,obtenerCondicionesEnCache}from"./performance.js";const API_BASE=window.API_BASE||"https://api-meteoarchidona.onrender.com";const CODIGOS_ESTACION=["EL_SILO","LOS_LLANOS"];const NOMBRES_NIVEL_LLUVIA={0:"Sin lluvia",1:"Débil",2:"Moderada",3:"Fuerte",4:"Muy fuerte"};const lluviaReal={EL_SILO:0,LOS_LLANOS:0};const lluviaSimulada={EL_SILO:0,LOS_LLANOS:0,GLOBAL:0};const vientoEstacion={EL_SILO:{direccion:null,velocidad:0},LOS_LLANOS:{direccion:null,velocidad:0}};function obtenerNivelEfectivo(codigo){return Math.max(lluviaReal[codigo]||0,lluviaSimulada[codigo]||0)}function obtenerVientoGlobal(codigosActivos){if(codigosActivos.length===0){return{direccion:null,velocidad:0}}const activos=codigosActivos.filter(codigo=>vientoEstacion[codigo]?.velocidad>0);if(activos.length===0){return{direccion:null,velocidad:0}}const velocidadMedia=activos.reduce((sum,codigo)=>sum+vientoEstacion[codigo].velocidad,0)/activos.length;const direccionesValidas=activos.map(codigo=>vientoEstacion[codigo].direccion).filter(d=>d!==null);if(direccionesValidas.length===0){return{direccion:null,velocidad:velocidadMedia}}const sinSum=direccionesValidas.reduce((sum,d)=>sum+Math.sin(d*Math.PI/180),0);const cosSum=direccionesValidas.reduce((sum,d)=>sum+Math.cos(d*Math.PI/180),0);const direccionMedia=Math.atan2(sinSum,cosSum)*(180/Math.PI);return{direccion:normalizarGrados(direccionMedia),velocidad:velocidadMedia}}function normalizarGrados(grados){if(grados===null||grados===undefined||Number.isNaN(Number(grados))){return null}return(Number(grados)%360+360)%360}function obtenerDireccionCardinal(grados){const valor=normalizarGrados(grados);if(valor===null){return"--"}const direcciones=["N","NNE","NE","ENE","E","ESE","SE","SSE","S","SSO","SO","OSO","O","ONO","NO","NNO"];const indice=Math.round(valor/22.5)%16;return direcciones[indice]}function actualizarVeleta(codigo,grados){const valor=normalizarGrados(grados);const veleta=obtenerElemento(`veleta-${codigo}`);if(valor===null){asignarTexto(`direccion-${codigo}`,"--");asignarTexto(`grados-${codigo}`,"--°");if(veleta){veleta.style.setProperty("--angulo","0deg")}return}asignarTexto(`direccion-${codigo}`,obtenerDireccionCardinal(valor));asignarTexto(`grados-${codigo}`,`${Math.round(valor)}°`);if(veleta){veleta.style.setProperty("--angulo",`${valor}deg`)}}function calcularMovimientoViento(direccionMeteorologica,velocidadKmh,ancho,alto){const direccion=normalizarGrados(direccionMeteorologica);const velocidad=Number.isFinite(Number(velocidadKmh))?Math.max(0,Number(velocidadKmh)):0;if(direccion===null){return{destino:180,vectorX:0,vectorY:1,componenteSur:true,inicioX:0,finalX:0,recorridoY:Math.max(alto*1.45,500),angulo:0,fuerza:0}}const destino=(direccion+180)%360;const radianes=destino*Math.PI/180;const vectorX=Math.sin(radianes);const vectorY=-Math.cos(radianes);const fuerza=limitar(velocidad/50,0,1);const derivaBase=ancho*(.035+fuerza*.33);const finalX=vectorX*derivaBase;const inicioX=-finalX*.1;const recorridoBase=Math.max(alto*1.45,500);const recorridoY=recorridoBase+vectorY*fuerza*alto*.16;const angulo=Math.atan2(finalX,Math.max(recorridoY,1))*180/Math.PI;const componenteSur=vectorY>.08;return{destino:destino,vectorX:vectorX,vectorY:vectorY,componenteSur:componenteSur,inicioX:inicioX,finalX:finalX,recorridoY:recorridoY,angulo:angulo,fuerza:fuerza}}function aplicarNivelACapa(capa,nivel){if(!capa){return}capa.classList.remove("activa","nivel-1","nivel-2","nivel-3","nivel-4");if(nivel<=0){return}capa.classList.add("activa",`nivel-${nivel}`)}function aplicarVientoACapa(capa,viento){if(!capa){return null}let referencia;if(capa.classList.contains("capa-lluvia-ficha")){referencia=capa.parentElement}else{referencia=document.documentElement}const ancho=referencia?.clientWidth||window.innerWidth||360;const alto=referencia?.clientHeight||window.innerHeight||700;const movimiento=calcularMovimientoViento(viento.direccion,viento.velocidad,ancho,alto);capa.style.setProperty("--inicio-x",`${movimiento.inicioX.toFixed(1)}px`);capa.style.setProperty("--final-x",`${movimiento.finalX.toFixed(1)}px`);capa.style.setProperty("--recorrido-y",`${movimiento.recorridoY.toFixed(1)}px`);capa.style.setProperty("--angulo-gota",`${movimiento.angulo.toFixed(2)}deg`);return movimiento}function configurarCapaCristal(capa,nivel,movimiento){if(!capa){return}capa.dataset.nivel=String(nivel);capa.dataset.vectorX=movimiento?String(movimiento.vectorX):"0";capa.classList.remove("activa");if(nivel<=0||!movimiento||!movimiento.componenteSur){return}capa.classList.add("activa")}function actualizarCapaMeteorologica(idLluvia,idCristal,nivel,viento){const capaLluvia=obtenerElemento(idLluvia);const capaCristal=obtenerElemento(idCristal);aplicarNivelACapa(capaLluvia,nivel);const movimiento=aplicarVientoACapa(capaLluvia,viento);configurarCapaCristal(capaCristal,nivel,movimiento)}function actualizarSistemaLluvia(){const nivelSilo=obtenerNivelEfectivo("EL_SILO");const nivelLlanos=obtenerNivelEfectivo("LOS_LLANOS");const activos=[];if(nivelSilo>0){activos.push("EL_SILO")}if(nivelLlanos>0){activos.push("LOS_LLANOS")}let nivelGlobalAutomatico=0;let nivelLocalSilo=0;let nivelLocalLlanos=0;if(activos.length===2){nivelGlobalAutomatico=Math.max(nivelSilo,nivelLlanos)}if(activos.length===1){if(activos[0]==="EL_SILO"){nivelLocalSilo=nivelSilo}else{nivelLocalLlanos=nivelLlanos}}const nivelGlobal=Math.max(nivelGlobalAutomatico,lluviaSimulada.GLOBAL||0);actualizarCapaMeteorologica("capa-lluvia-EL_SILO","capa-gotas-cristal-EL_SILO",nivelLocalSilo,vientoEstacion.EL_SILO);actualizarCapaMeteorologica("capa-lluvia-LOS_LLANOS","capa-gotas-cristal-LOS_LLANOS",nivelLocalLlanos,vientoEstacion.LOS_LLANOS);const vientoGlobal=obtenerVientoGlobal(activos);actualizarCapaMeteorologica("capa-lluvia","capa-gotas-cristal",nivelGlobal,vientoGlobal)}function actualizarIndicadorSimulacion(origen){const elemento=obtenerElemento(`simulacion-${origen}`);if(!elemento){return}const nivel=lluviaSimulada[origen]||0;if(nivel<=0){elemento.classList.remove("visible");elemento.textContent="";return}if(origen==="GLOBAL"){elemento.textContent=`Prueba ${NOMBRES_NIVEL_LLUVIA[nivel]}`}else{elemento.textContent=`Prueba lluvia · ${NOMBRES_NIVEL_LLUVIA[nivel]}`}elemento.classList.add("visible")}function avanzarSimulacion(origen){const actual=lluviaSimulada[origen]||0;let siguiente;if(actual<=0||actual>=4){siguiente=1}else{siguiente=actual+1}lluviaSimulada[origen]=siguiente;actualizarIndicadorSimulacion(origen);actualizarSistemaLluvia()}function desactivarSimulacion(origen){lluviaSimulada[origen]=0;actualizarIndicadorSimulacion(origen);actualizarSistemaLluvia()}function inicializarGotasEnCapa(idCapa,totalGotas=160){const capa=obtenerElemento(idCapa);if(!capa){return}for(let indice=0;indice<totalGotas;indice+=1){const gota=document.createElement("span");gota.className="gota-lluvia";const x=Math.random()*116-8;const longitud=13+Math.random()*27;const duracion=.58+Math.random()*.42;const retraso=-Math.random()*2.4;const opacidad=.38+Math.random()*.57;gota.style.setProperty("--x",`${x}%`);gota.style.setProperty("--longitud",`${longitud}px`);gota.style.setProperty("--duracion",`${duracion}s`);gota.style.setProperty("--retraso",`${retraso}s`);gota.style.setProperty("--opacidad",opacidad.toFixed(2));capa.appendChild(gota)}}function inicializarLluviaVisual(){inicializarGotasEnCapa("capa-lluvia",160);inicializarGotasEnCapa("capa-lluvia-EL_SILO",160);inicializarGotasEnCapa("capa-lluvia-LOS_LLANOS",160)}function obtenerMaximoGotasCristal(nivel,esGlobal){const limitesGlobales={1:4,2:7,3:11,4:16};const limitesLocales={1:3,2:5,3:8,4:11};return esGlobal?limitesGlobales[nivel]||0:limitesLocales[nivel]||0}function obtenerProbabilidadGotaCristal(nivel){const probabilidades={1:.16,2:.34,3:.62,4:.88};return probabilidades[nivel]||0}function crearGotaCristal(capa,nivel){if(!capa||nivel<=0){return}const esGlobal=capa.classList.contains("capa-gotas-cristal");const maximo=obtenerMaximoGotasCristal(nivel,esGlobal);const gotasActuales=capa.querySelectorAll(".gota-cristal").length;if(gotasActuales>=maximo){return}const gota=document.createElement("span");gota.className="gota-cristal";const x=4+Math.random()*92;const y=4+Math.random()*76;const baseTamano={1:5,2:6,3:7,4:8}[nivel];const rangoTamano={1:4,2:6,3:8,4:10}[nivel];const tamano=baseTamano+Math.random()*rangoTamano;const vida=2600+Math.random()*3400;const opacidad=.15+Math.random()*(.06+nivel*.025);const deslizar=8+nivel*5+Math.random()*14;const vectorX=Number(capa.dataset.vectorX)||0;const desvioX=vectorX*(3+nivel*2);gota.style.setProperty("--x",`${x}%`);gota.style.setProperty("--y",`${y}%`);gota.style.setProperty("--tamano",`${tamano.toFixed(1)}px`);gota.style.setProperty("--vida",`${Math.round(vida)}ms`);gota.style.setProperty("--opacidad-cristal",opacidad.toFixed(2));gota.style.setProperty("--deslizar",`${deslizar.toFixed(1)}px`);gota.style.setProperty("--desvio-x",`${desvioX.toFixed(1)}px`);capa.appendChild(gota);window.setTimeout(()=>{gota.remove()},vida+150)}function generarGotasCristalActivas(){if(window.matchMedia("(prefers-reduced-motion: reduce)").matches){return}const capas=document.querySelectorAll(".capa-gotas-cristal.activa, "+".capa-gotas-cristal-ficha.activa");capas.forEach(capa=>{const nivel=Number(capa.dataset.nivel)||0;if(nivel<=0){return}const probabilidad=obtenerProbabilidadGotaCristal(nivel);if(Math.random()>probabilidad){return}const cantidad=nivel>=4&&Math.random()>.48?2:1;for(let indice=0;indice<cantidad;indice+=1){crearGotaCristal(capa,nivel)}})}function configurarControlLluvia(elemento,origen){let temporizadorLargo=null;let pulsacionLarga=false;let ultimoToque=0;let inicioX=0;let inicioY=0;function cancelarTemporizador(){if(temporizadorLargo!==null){clearTimeout(temporizadorLargo);temporizadorLargo=null}}elemento.addEventListener("pointerdown",evento=>{pulsacionLarga=false;inicioX=evento.clientX;inicioY=evento.clientY;cancelarTemporizador();temporizadorLargo=setTimeout(()=>{pulsacionLarga=true;ultimoToque=0;desactivarSimulacion(origen)},700)});elemento.addEventListener("pointermove",evento=>{const desplazamientoX=Math.abs(evento.clientX-inicioX);const desplazamientoY=Math.abs(evento.clientY-inicioY);if(desplazamientoX>12||desplazamientoY>12){cancelarTemporizador()}});elemento.addEventListener("pointercancel",()=>{cancelarTemporizador();pulsacionLarga=false});elemento.addEventListener("pointerup",evento=>{cancelarTemporizador();if(pulsacionLarga){pulsacionLarga=false;return}const ahora=Date.now();if(ultimoToque>0&&ahora-ultimoToque<450){ultimoToque=0;avanzarSimulacion(origen);evento.preventDefault();return}ultimoToque=ahora});elemento.addEventListener("contextmenu",evento=>{evento.preventDefault()});elemento.addEventListener("keydown",evento=>{if(evento.key==="Enter"){evento.preventDefault();avanzarSimulacion(origen)}if(evento.key==="Escape"){evento.preventDefault();desactivarSimulacion(origen)}})}function configurarControlesLluvia(){const controles=document.querySelectorAll("[data-lluvia-control]");controles.forEach(control=>{const origen=control.dataset.lluviaControl;if(!origen){return}configurarControlLluvia(control,origen)})}function configurarPatrocinios(){const controles=document.querySelectorAll(".patrocinio-estacion-control");controles.forEach(control=>{control.addEventListener("click",()=>{const codigo=control.dataset.patrocinio;const patrocinio=obtenerElemento(`patrocinio-${codigo}`);if(!patrocinio){return}const pausado=patrocinio.classList.toggle("pausado");control.textContent=pausado?"▶":"Ⅱ";control.setAttribute("aria-pressed",String(pausado));control.setAttribute("aria-label",pausado?"Reanudar patrocinio":"Pausar patrocinio")})})}function mostrarLluvia(codigo,datos){const lluviaDia=formatearNumero(datos.lluvia_dia_mm);const lluviaMes=formatearNumero(datos.lluvia_mes_mm);const lluviaAnio=formatearNumero(datos.lluvia_anio_agricola_mm);const tasaLluvia=formatearNumero(datos.tasa_lluvia_mm_h);const nivelReal=nivelLluviaDesdeTasa(datos.tasa_lluvia_mm_h);lluviaReal[codigo]=nivelReal;const icono=obtenerIconoLluvia(nivelReal);asignarTexto(`lluvia-tasa-${codigo}`,`${tasaLluvia} mm/h`);asignarTexto(`lluvia-dia-${codigo}`,`${lluviaDia} mm`);asignarTexto(`lluvia-mes-${codigo}`,`${lluviaMes} mm`);asignarTexto(`lluvia-anio-${codigo}`,`${lluviaAnio} mm`);asignarTexto(`lluvia-estado-${codigo}`,NOMBRES_NIVEL_LLUVIA[nivelReal]);asignarTexto(`lluvia-icono-actual-${codigo}`,icono);asignarTexto(`lluvia-resumen-icono-dia-${codigo}`,icono);asignarTexto(`lluvia-resumen-icono-mes-${codigo}`,icono);asignarTexto(`lluvia-resumen-icono-anio-${codigo}`,icono);actualizarSistemaLluvia()}function actualizarPieEstado(codigo,temperatura,hora){asignarTexto(`pie-temp-${codigo}`,temperatura===null?"--":`${temperatura} °C`);if(hora){asignarTexto("pie-hora",hora)}const franja=obtenerElemento("pie-estado");if(!franja){return}const hayDatos=CODIGOS_ESTACION.some(c=>{const e=obtenerElemento(`pie-temp-${c}`);return e&&e.textContent!=="--"});franja.classList.toggle("visible",hayDatos)}function mostrarDatosEstacion(codigo,datos){asignarTexto(`nombre-${codigo}`,datos.nombre_estacion);asignarHtml(`temperatura-${codigo}`,`${formatearNumero(datos.temperatura_c)}<sup>°C</sup>`);asignarTexto(`sensacion-${codigo}`,`Sensación ${formatearNumero(datos.indice_calor_c)} °C`);const horaExterior=datos.hora_observacion_exterior||datos.hora_observacion||"--:--";const fechaExterior=datos.fecha_observacion_exterior||datos.fecha_observacion||"--";const horaBarometro=datos.hora_observacion_barometro||datos.hora_observacion||"--:--";asignarTexto(`observacion-${codigo}`,`Exterior ${horaExterior}`);asignarTexto(`fecha-${codigo}`,fechaExterior);asignarTexto(`humedad-${codigo}`,`${formatearNumero(datos.humedad_pct)} %`);asignarTexto(`rocio-${codigo}`,`${formatearNumero(datos.punto_rocio_c)} °C`);asignarTexto(`presion-${codigo}`,`${formatearNumero(datos.presion_hpa)} hPa`);asignarTexto(`presion-hora-${codigo}`,`Barómetro ${horaBarometro}`);asignarTexto(`radiacion-${codigo}`,`${formatearNumero(datos.radiacion_solar_w_m2,0)} W/m²`);asignarTexto(`uv-${codigo}`,formatearNumero(datos.indice_uv));asignarTexto(`uv-estado-${codigo}`,clasificarUv(datos.indice_uv));asignarHtml(`viento-actual-${codigo}`,`${formatearNumero(datos.viento_actual_kmh)} <small>km/h</small>`);asignarTexto(`viento-2m-${codigo}`,`${formatearNumero(datos.viento_medio_2_min_kmh)} km/h`);asignarTexto(`viento-10m-${codigo}`,`${formatearNumero(datos.viento_medio_10_min_kmh)} km/h`);asignarTexto(`racha-${codigo}`,`${formatearNumero(datos.racha_10_min_kmh)} km/h`);vientoEstacion[codigo]={direccion:normalizarGrados(datos.direccion_viento_grados),velocidad:Number.isFinite(Number(datos.viento_actual_kmh))?Number(datos.viento_actual_kmh):0};actualizarVeleta(codigo,datos.direccion_viento_grados);const estado=obtenerElemento(`estado-${codigo}`);if(estado){estado.innerHTML='<span class="punto"></span>En línea'}actualizarPieEstado(codigo,formatearNumero(datos.temperatura_c),horaExterior);mostrarLluvia(codigo,datos)}function mostrarErrorLluvia(codigo){lluviaReal[codigo]=0;asignarTexto(`lluvia-tasa-${codigo}`,"-- mm/h");asignarTexto(`lluvia-dia-${codigo}`,"-- mm");asignarTexto(`lluvia-mes-${codigo}`,"-- mm");asignarTexto(`lluvia-anio-${codigo}`,"-- mm");asignarTexto(`lluvia-estado-${codigo}`,"--");asignarTexto(`lluvia-icono-actual-${codigo}`,"☁️");asignarTexto(`lluvia-resumen-icono-dia-${codigo}`,"☁️");asignarTexto(`lluvia-resumen-icono-mes-${codigo}`,"☁️");asignarTexto(`lluvia-resumen-icono-anio-${codigo}`,"☁️");actualizarSistemaLluvia()}function mostrarErrorEstacion(codigo){vientoEstacion[codigo]={direccion:null,velocidad:0};asignarTexto(`estado-${codigo}`,"Sin datos");asignarHtml(`temperatura-${codigo}`,"--<sup>°C</sup>");asignarTexto(`sensacion-${codigo}`,"Sensación -- °C");asignarTexto(`observacion-${codigo}`,"Exterior --:--");asignarTexto(`humedad-${codigo}`,"-- %");asignarTexto(`rocio-${codigo}`,"-- °C");asignarTexto(`presion-${codigo}`,"-- hPa");asignarTexto(`presion-hora-${codigo}`,"Barómetro --:--");asignarTexto(`radiacion-${codigo}`,"-- W/m²");asignarTexto(`uv-${codigo}`,"--");asignarTexto(`uv-estado-${codigo}`,"--");asignarTexto(`fecha-${codigo}`,"--");asignarHtml(`viento-actual-${codigo}`,"-- <small>km/h</small>");asignarTexto(`viento-2m-${codigo}`,"-- km/h");asignarTexto(`viento-10m-${codigo}`,"-- km/h");asignarTexto(`racha-${codigo}`,"-- km/h");actualizarVeleta(codigo,null);actualizarPieEstado(codigo,null,null);mostrarErrorLluvia(codigo)}async function cargarEstacion(codigo){try{if(!esEstacionValida(codigo)){console.error("Estación inválida:",codigo);mostrarErrorEstacion(codigo);return}const datos=await obtenerCondicionesEnCache(codigo,`${API_BASE}/condiciones-actuales`);const validacion=validarCondiciones({estacion:codigo,temperatura_celsius:datos.temperatura_c,humedad_relativa:datos.humedad_pct,presion_mb:datos.presion_hpa,velocidad_viento_kmh:datos.viento_actual_kmh,direccion_viento_grados:datos.direccion_viento_grados,tasa_lluvia_mm_h:datos.tasa_lluvia_mm_h,indice_uv:datos.indice_uv});if(!validacion.valido){console.error("Datos inválidos:",validacion.errores);mostrarErrorEstacion(codigo);return}mostrarDatosEstacion(codigo,datos)}catch(error){console.error(`Error cargando ${codigo}:`,error);mostrarErrorEstacion(codigo)}}async function cargarCondiciones(){await Promise.all([cargarEstacion("EL_SILO"),cargarEstacion("LOS_LLANOS")])}let temporizadorResize=null;window.addEventListener("resize",()=>{if(temporizadorResize!==null){clearTimeout(temporizadorResize)}temporizadorResize=setTimeout(()=>{actualizarSistemaLluvia();temporizadorResize=null},180)});function iniciarAplicacion(){inicializarLluviaVisual();configurarControlesLluvia();inicializarReloj();configurarPatrocinios();inicializarNavegacion();actualizarSistemaLluvia();inicializarPerformance();cargarCondiciones();setInterval(cargarCondiciones,6e4);setInterval(generarGotasCristalActivas,420)}window.iniciarAplicacion=iniciarAplicacion;window.dispatchEvent(new Event("app-lista"));